package com.mannaggia.app

import android.content.Context
import kotlinx.coroutines.Dispatchers
import kotlinx.coroutines.withContext
import java.util.Calendar
import java.util.Locale

/**
 * Shared saint-picking logic — the port of mannaggia.sh lives here so it can be
 * called from MainActivity, MannaggiaTileService and MannaggiaWidgetProvider.
 *
 * Saints come from assets/santi.txt and feast days from assets/feste.tsv
 * (Wikidata, CC0), both generated by tools/genera_santi.py, so the app works offline.
 */
object Mannaggia {

    private const val SAINTS_ASSET = "santi.txt"
    private const val FEASTS_ASSET = "feste.tsv"

    @Volatile
    private var saints: List<String>? = null

    /** "MM-dd" → saints celebrated that day, most famous first. */
    @Volatile
    private var feasts: Map<String, List<String>>? = null

    /**
     * Build the final phrase shown (and spoken) to the user: "Mannaggia <saint>!", or for
     * the special cards their own invocation, "<saint>, proteggici da ...!".
     */
    fun phraseOf(saint: String): String = ESCLAMAZIONI[saint] ?: "Mannaggia $saint!"

    /** The special cards (trophy rewards, see Trofei) don't curse: they protect. */
    private val ESCLAMAZIONI = mapOf(
        "Santo Subito" to "Santo Subito, proteggici da chi non apre le change request!",
        "San Culo" to "San Culo, proteggici dai backup mai testati!",
        "San Calendario" to "San Calendario, proteggici dai certificati TLS scaduti!",
        "San Deploy" to "San Deploy, proteggici dai rilasci in produzione del venerdì alle 18!",
        "San Sudo" to "San Sudo, proteggici dai permessi 777!",
        "Santa Pazienza" to "Santa Pazienza, proteggici dagli utenti che «hanno già riavviato»!",
        // mannaggia.sh: "...ti strafulmini santa cunegonda bipalluta protrettice dei VUA".
        "Santa Cunegonda Bipalluta" to "Santa Cunegonda Bipalluta, proteggici da systemd!",
    )

    /** Number of saints in the bundled list (the album's 100%). */
    suspend fun saintCount(context: Context): Int = withContext(Dispatchers.IO) {
        (saints ?: loadSaints(context).also { saints = it }).size
    }

    /** Pick a random saint from the bundled list (loaded once, then cached). */
    suspend fun randomSaint(context: Context): String = withContext(Dispatchers.IO) {
        val list = saints ?: loadSaints(context).also { saints = it }
        // Unlocked special cards (trophy rewards) can come out too, like any saint.
        val pool = list + Trofei.unlockedSpecials(context)
        if (pool.isEmpty()) "Sant'Anonimo" else pool.random()
    }

    /** The saint of the day: the most famous one celebrated today, or null if none. */
    suspend fun saintOfDay(context: Context): String? = withContext(Dispatchers.IO) {
        val map = feasts ?: loadFeasts(context).also { feasts = it }
        // java.time needs API 26 (minSdk is 24), hence Calendar.
        val today = Calendar.getInstance()
        val key = String.format(Locale.ROOT, "%02d-%02d",
            today.get(Calendar.MONTH) + 1, today.get(Calendar.DAY_OF_MONTH))
        map[key]?.firstOrNull()
    }

    /** Feast days of [saint] as "MM-dd", in calendar order (empty if unknown). */
    suspend fun feastsOf(context: Context, saint: String): List<String> = withContext(Dispatchers.IO) {
        val map = feasts ?: loadFeasts(context).also { feasts = it }
        map.filterValues { saint in it }.keys.sorted()
    }

    /** Read assets/santi.txt, skipping blank lines and `#` comments. */
    private fun loadSaints(context: Context): List<String> = readLines(context, SAINTS_ASSET)

    /** Read assets/feste.tsv (MM-DD<TAB>santo), keeping the file order within each day. */
    private fun loadFeasts(context: Context): Map<String, List<String>> =
        readLines(context, FEASTS_ASSET)
            .mapNotNull { line -> line.split('\t').takeIf { it.size == 2 } }
            .groupBy({ it[0] }, { it[1] })

    private fun readLines(context: Context, asset: String): List<String> =
        context.applicationContext.assets.open(asset).bufferedReader(Charsets.UTF_8).useLines { lines ->
            lines.map { it.trim() }
                .filter { it.isNotEmpty() && !it.startsWith("#") }
                .toList()
        }
}
